import heapq

class Node:
    def __init__(self, position, cost=0, parent=None):
        self.position = position
        self.cost = cost
        self.parent = parent

    def __lt__(self, other):
        return self.cost + self.heuristic_cost < other.cost + other.heuristic_cost

def manhattan_distance(node1, node2):
    """Calculates the Manhattan distance between two nodes."""
    return abs(node1.position[0] - node2.position[0]) + abs(node1.position[1] - node2.position[1])

def best_first_search(start, goal, heuristic):
    """Performs a best-first search with a heuristic function."""

    open_list = []  # Priority queue for nodes to explore
    heapq.heappush(open_list, (0, start))  # Initialize with initial cost 0 and start node

    closed_set = set()

    while open_list:
        current_cost, current_node = heapq.heappop(open_list)

        if current_node == goal:
            return reconstruct_path(current_node)

        closed_set.add(current_node)

        if current_node in closed_set:
            continue

        for neighbor in get_neighbors(current_node):
            neighbor_cost =  current_node.cost + heuristic(neighbor, current_node)

            if neighbor not in closed_set:
                new_node = Node(neighbor, neighbor_cost, current_node)
                heapq.heappush(open_list, (neighbor_cost, new_node))

    return None  # No path found


def get_neighbors(node):
    """Returns a list of neighboring nodes."""
    # Implement your logic to get neighbors here
    # Example: Assuming a 2D grid
    return [(node.position[0] + 1, node.position[1]), (node.position[0] - 1, node.position[1]), 
            (node.position[0], node.position[1] + 1), (node.position[0], node.position[1] - 1)]


def reconstruct_path(node):
    """Reconstructs the path from the goal node back to the start node."""
    path = [node]
    current = node
    while current.parent:
        path.append(current.parent)
        current = current.parent
    return path[::-1]


def manhattan_distance_heuristic(node, goal):
    """Calculates the Manhattan distance between two nodes."""
    return abs(node.position[0] - goal.position[0]) + abs(node.position[1] - goal.position[1])


